/*updateSellerMpRqBulkQuotationPriceReg*/
UPDATE KEP_BURQ_RFQ
SET CH_LIST_PRICE = #{CH_LIST_PRICE},							
	CHANGE_DATE = SYSDATE,
	CHANGE_USER_ID = #{USER_ID}
WHERE BURQ_NO = #{st_burq_no}
AND	BURQ_RFQ_NO = #{BURQ_RFQ_NO}
AND AGENT = #{COM_CODE}
AND STATUS = 'K1'
